import type { PanelSurface } from '../features/visualizer/engine.ts';
import { catalogProducts } from './catalog-data.ts';

/**
 * NEW DEC panels verified from the business's own showroom videos (see RESEARCH.md).
 * Names are descriptive: NEW DEC publishes no product codes. Sizes and thicknesses appear only
 * where NEW DEC stated them on screen. Product records and textures are generated by
 * scripts/assets/build_textures.py into catalog-data.ts.
 */
export type CategoryId = 'marble' | 'exotic' | 'wood' | 'slat' | 'stone' | 'plain';

export const categories: Record<CategoryId, { name: string; short: string }> = {
  marble: { name: 'Մարմարի տեսքով մեծաչափ թերթեր', short: 'Մարմար' },
  exotic: { name: 'Էկզոտիկ քարի և օնիքսի տեսքով թերթեր', short: 'Էկզոտիկ քար' },
  wood: { name: 'Փայտի և տրավերտինի տեսքով վահանակներ', short: 'Փայտ' },
  slat: { name: 'Ռեյկային և ակոսավոր վահանակներ', short: 'Ռեյկային' },
  stone: { name: 'Քարի ռելիեֆով վահանակներ', short: 'Ռելիեֆ քար' },
  plain: { name: 'Միագույն վահանակներ', short: 'Միագույն' },
};

export interface Product {
  id: string;
  name: string;
  category: CategoryId;
  /** Surface character shown as a badge, e.g. «Փայլուն», «Մատ», «Ռելիեֆ». */
  finish: string;
  /** Only when NEW DEC stated it, e.g. «2,80 × 1,22 մ». */
  size?: string;
  thickness?: string;
  /** Options the visitor can name in a request (sizes / thicknesses NEW DEC offers for this type). */
  variants: string[];
  /** Catalog card image (4:5) and visualizer swatch (3:4). */
  image: string;
  thumb: string;
  alt: string;
  surface: PanelSurface;
  /** Where the reference comes from: TikTok video id and frame. */
  /** NEW DEC's own TikTok video the reference was photographed from, and the moment used. */
  source: { video: string; time: string };
}

export const products: Product[] = catalogProducts;

/** Area of one sheet or tile, used for the "how many sheets" hints. */
export function sheetArea(p: Product): { area: number; label: string } | null {
  const w = p.surface.moduleW;
  const h = p.surface.moduleH;
  if (!w || !h) return null;
  const fmt = (n: number) => n.toFixed(2).replace('.', ',');
  return { area: w * h, label: `${fmt(h)} × ${fmt(w)} մ` };
}

export function sourceUrl(p: Product): string {
  return `https://www.tiktok.com/@newdec_yvn/video/${p.source.video}`;
}
